[CmdletBinding()]param([string]$RepositoryRoot=(Resolve-Path(Join-Path $PSScriptRoot '..\..')).Path)
Set-StrictMode -Version 2.0;$ErrorActionPreference='Stop'
$runner=Join-Path $RepositoryRoot 'Modules\ObjectControl\Invoke-MSADPTDirectoryControlEffectiveAccess-v1.0.0.ps1';if(-not(Test-Path -LiteralPath $runner -PathType Leaf)){throw "RunnerMissing: $runner"}
$t=$null;$e=$null;[void][Management.Automation.Language.Parser]::ParseFile($runner,[ref]$t,[ref]$e);if(@($e).Count){throw "ParserFailure: $(@($e|ForEach-Object{$_.Message})-join'; ')"}
$temp=Join-Path ([IO.Path]::GetTempPath()) ('MSADPT-EA-'+[guid]::NewGuid().ToString('N'));$ev=Join-Path $temp 'evidence';$red=Join-Path $temp 'reduction';$out=Join-Path $temp 'out';New-Item -ItemType Directory -Path $ev,$red|Out-Null
try{
 $sid='S-1-5-21-1-1100';$dn='CN=Tier0,DC=example,DC=test'
 @([pscustomobject]@{CandidateId='C1';Priority='P1';Trustee='EXAMPLE\Operator';TrusteeSid=$sid;TargetName='Tier0';TargetDistinguishedName=$dn;TargetObjectType='Group';Capability='GenericAll'},[pscustomobject]@{CandidateId='C2';Priority='P2';Trustee='EXAMPLE\Operator';TrusteeSid=$sid;TargetName='Server1';TargetDistinguishedName='CN=Server1,DC=example,DC=test';TargetObjectType='Computer';Capability='WriteRBCD'})|Export-Csv (Join-Path $red 'directory-control-prioritized-target-details.csv') -NoTypeInformation
 @([pscustomobject]@{TargetObjectType='Group';TargetName='Tier0';TargetDistinguishedName=$dn;Trustee='EXAMPLE\Operator';TrusteeSid=$sid;AccessControlType='Allow';ActiveDirectoryRights='GenericAll';ObjectTypeGuid='00000000-0000-0000-0000-000000000000';InheritedObjectTypeGuid='00000000-0000-0000-0000-000000000000';IsInherited=$false},[pscustomobject]@{TargetObjectType='Computer';TargetName='Server1';TargetDistinguishedName='CN=Server1,DC=example,DC=test';Trustee='EXAMPLE\Operator';TrusteeSid=$sid;AccessControlType='Allow';ActiveDirectoryRights='WriteProperty';ObjectTypeGuid='3f78c3e5-f79a-46bd-a0b8-9d18116ddc79';InheritedObjectTypeGuid='00000000-0000-0000-0000-000000000000';IsInherited=$false},[pscustomobject]@{TargetObjectType='Computer';TargetName='Server1';TargetDistinguishedName='CN=Server1,DC=example,DC=test';Trustee='EXAMPLE\Operator';TrusteeSid=$sid;AccessControlType='Deny';ActiveDirectoryRights='WriteProperty';ObjectTypeGuid='3f78c3e5-f79a-46bd-a0b8-9d18116ddc79';InheritedObjectTypeGuid='00000000-0000-0000-0000-000000000000';IsInherited=$false})|Export-Csv (Join-Path $ev 'directory-control-ace-inventory.csv') -NoTypeInformation
 @([pscustomobject]@{PrincipalSid=$sid;TokenSid=$sid;Source='Self';Depth=0;Complete=$true})|Export-Csv (Join-Path $temp 'token.csv') -NoTypeInformation
 $r=@(& $runner -DirectoryControlEvidenceDirectory $ev -CandidateReductionDirectory $red -OutputDirectory $out -TokenEvidencePath (Join-Path $temp 'token.csv') -NoColor);$terminal=@($r|Where-Object{$_.PSObject.Properties['ModuleId']})|Select-Object -Last 1;if($null-eq$terminal-or$terminal.Status-ne'Passed'){throw 'TerminalResultFailed'}
 $rows=@(Import-Csv (Join-Path $out 'directory-control-effective-access-evaluations.csv'));if($rows.Count-ne2){throw 'EvaluationCountFailed'};if(@($rows|Where-Object{$_.CandidateId-eq'C1'}).Disposition-ne'EffectiveControlConfirmed'){throw 'AllowEvaluationFailed'};if(@($rows|Where-Object{$_.CandidateId-eq'C2'}).Disposition-ne'EffectiveControlNotEstablished'){throw 'DenyEvaluationFailed'}
 [pscustomobject]@{Status='Passed';TestVersion='1.0.0';Evaluations=2;AllowConfirmed=$true;DenyApplied=$true;NetworkActivity='None';RemoteChanges='None'}
}finally{Remove-Item -LiteralPath $temp -Recurse -Force -ErrorAction SilentlyContinue}
